__factories["PetSim99.luau"] = function(__require)
--!nocheck
-- Experimental legacy coin protocol; current Classic Event support requires a live probe.
-- Native module access only. No hooks, upvalues, or authentication bypasses.
local PetSim99 = {}
PetSim99.__index = PetSim99
local Config = __require("Config.luau")

local function supportedNone()
    return { AutoFarm = false, AutoCollectOrbs = false, AutoCollectLootbags = false, WalkToTarget = false }
end

local function finite(value)
    return type(value) == "number" and value == value and value > -math.huge and value < math.huge
end

local function identifier(value)
    return (type(value) == "string" and value ~= "") or finite(value)
end

local function vector(value)
    return typeof(value) == "Vector3" and finite(value.X) and finite(value.Y) and finite(value.Z)
end

local function childSummary(parent, limit)
    if not parent then return "not present" end
    local names = {}
    for _, child in ipairs(parent:GetChildren()) do
        table.insert(names, child.Name .. " (" .. child.ClassName .. ")")
    end
    table.sort(names)
    local total = #names
    while #names > limit do table.remove(names) end
    local result = table.concat(names, ", ")
    if total > limit then result ..= string.format(" ... (%d more)", total - limit) end
    return if result == "" then "empty" else result
end

local function requireModule(module, path)
    if not module or not module:IsA("ModuleScript") then
        error(path .. " is not an available ModuleScript. Reconnect after the event finishes loading.", 0)
    end
    local ok, value = pcall(require, module)
    if not ok then
        error("Native require of " .. path .. " failed: " .. tostring(value)
            .. ". Module access may be unsupported by this executor; no bypass is attempted.", 0)
    end
    if type(value) ~= "table" then error(path .. " returned an unsupported value; expected a table.", 0) end
    return value
end

local function physicalPosition(instance)
    if instance:IsA("BasePart") then return instance.Position end
    if instance:IsA("Model") then
        local part = instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart", true)
        if part then return part.Position end
    end
    return nil
end

function PetSim99.new()
    return setmetatable({
        Supported = supportedNone(),
        Reason = "Not connected. Reconnect inside the Classic Event to test the experimental coin protocol.",
        Report = "Not inspected yet.",
        _connected = false, _destroyed = false, _generation = 0,
        _cooldowns = setmetatable({}, { __mode = "k" }), _assigned = {},
        _counts = { FarmDispatches = 0, OrbIds = 0, LootbagIds = 0 },
    }, PetSim99)
end

function PetSim99:_report()
    self.Report = (self._diagnostics or "Not inspected yet.") .. "\nAdapter: " .. self.Reason
        .. string.format("\nRequests only: %d pet farm dispatches; %d orb IDs; %d lootbag IDs. No collection/break confirmation is inferred.",
            self._counts.FarmDispatches, self._counts.OrbIds, self._counts.LootbagIds)
end

function PetSim99:_block(message)
    self._connected = false
    self.Supported = supportedNone()
    self.Reason = tostring(message)
    self:_report()
end

function PetSim99:_fail(message)
    self:_block(message)
    error(message, 0)
end

function PetSim99:_root()
    local player = game:GetService("Players").LocalPlayer
    local character = player and player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root or not root:IsA("BasePart") or not vector(root.Position) then
        error("The character's HumanoidRootPart is unavailable. Wait for respawn and reconnect.", 0)
    end
    return root
end

function PetSim99:_call(method, command, ...)
    local ok, result = pcall(self._network[method], command, ...)
    if not ok then
        error(command .. " failed: " .. tostring(result)
            .. ". The event protocol or module access may differ; no bypass is attempted.", 0)
    end
    if result == false then error(command .. " was explicitly rejected by the game.", 0) end
    return result
end

function PetSim99:_readSnapshot(probe)
    local generation = self._generation
    local records = self:_call("Invoke", "Get Coins")
    if generation ~= self._generation or self._destroyed then error("Coin read canceled by reconnect or unload.", 0) end
    local root = self:_root()
    if type(records) ~= "table" then
        error("Get Coins returned an unsupported response; expected a dictionary of coin records.", 0)
    end
    if probe and next(records) == nil then
        error("Get Coins returned no records. Stand near loaded Classic Event coins and reconnect.", 0)
    end
    local candidates, assignments = {}, {}
    local allHealthKnown = true
    for id, raw in pairs(records) do
        if not identifier(id) or type(raw) ~= "table" or not vector(raw.p)
            or type(raw.a) ~= "string" or type(raw.n) ~= "string"
            or (raw.health ~= nil and (not finite(raw.health) or raw.health < 0)) then
            error("Get Coins returned an unknown coin schema. Farming is disabled rather than guessing a wrapper or field mapping.", 0)
        end
        local instance = self._coins:FindFirstChild(tostring(id))
        local coinPart = instance and instance:FindFirstChild("Coin")
        local areaAllowed = true
        if self._world and type(self._world.HasArea) == "function" then
            local ok, allowed = pcall(self._world.HasArea, raw.a)
            if not ok then error("WorldCmds.HasArea failed; reconnect before farming: " .. tostring(allowed), 0) end
            areaAllowed = allowed == true
        end
        if instance and instance:IsA("Model") and coinPart and coinPart:IsA("BasePart") and areaAllowed then
            local healthKnown = raw.health ~= nil
            allHealthKnown = allHealthKnown and healthKnown
            table.insert(candidates, {
                id = id, name = raw.n, area = raw.a,
                health = if healthKnown then raw.health else 1,
                healthKnown = healthKnown,
                distance = (root.Position - raw.p).Magnitude,
                position = raw.p, instance = instance,
            })
            local assigned = {}
            if type(raw.pets) == "table" then
                for _, uid in pairs(raw.pets) do
                    if identifier(uid) then assigned[tostring(uid)] = true end
                end
            end
            assignments[tostring(id)] = assigned
        end
    end
    if probe and #candidates == 0 then
        error("No valid Get Coins record matches a loaded __THINGS.Coins model with a Coin BasePart. Stand near event coins and reconnect.", 0)
    end
    local ok, equipped = pcall(self._petCmds.GetEquipped)
    if generation ~= self._generation or self._destroyed then error("Pet read canceled by reconnect or unload.", 0) end
    if not ok then error("PetCmds.GetEquipped failed: " .. tostring(equipped), 0) end
    if type(equipped) ~= "table" then error("PetCmds.GetEquipped returned an unsupported value; expected pet records.", 0) end
    local pets, seen = {}, {}
    for _, pet in pairs(equipped) do
        if type(pet) ~= "table" or not identifier(pet.uid) then
            error("PetCmds.GetEquipped returned an unknown pet record; expected a uid field.", 0)
        end
        local key = tostring(pet.uid)
        if not seen[key] then
            seen[key] = true
            table.insert(pets, pet.uid)
        end
    end
    self._assigned = assignments
    return { Candidates = candidates, Pets = pets, HealthKnown = #candidates > 0 and allHealthKnown }
end

function PetSim99:Connect()
    self._generation += 1
    local generation = self._generation
    self._destroyed, self._connected = false, false
    self.Supported = supportedNone()
    self._network, self._petCmds, self._world, self._coins, self._things = nil, nil, nil, nil, nil
    self._assigned = {}
    self._cooldowns = setmetatable({}, { __mode = "k" })
    local matches = game.PlaceId == Config.Target.PlaceId and game.GameId == Config.Target.UniverseId
    local storage = game:GetService("ReplicatedStorage")
    local library = storage:FindFirstChild("Library")
    local client = library and library:FindFirstChild("Client")
    local things = workspace:FindFirstChild("__THINGS")
    self._diagnostics = table.concat({
        "Target: PS99 Classic Event (not legacy standalone PSX)",
        "PlaceId: " .. tostring(game.PlaceId),
        "UniverseId: " .. tostring(game.GameId),
        "Observed event destination: " .. (if matches then "MATCH" else "DIFFERENT PLACE/UNIVERSE"),
        "ReplicatedStorage: " .. childSummary(storage, 50),
        "Library: " .. childSummary(library, 80),
        "Library.Client: " .. childSummary(client, 120),
        "Framework: " .. childSummary(storage:FindFirstChild("Framework"), 50),
        "Network: " .. childSummary(storage:FindFirstChild("Network"), 100),
        "Workspace: " .. childSummary(workspace, 40),
        "__THINGS: " .. childSummary(things, 60),
        "__DEBRIS: " .. childSummary(workspace:FindFirstChild("__DEBRIS"), 40),
    }, "\n")
    local ok, message = pcall(function()
        if not matches then
            error("Enter Classic Event place " .. tostring(Config.Target.PlaceId) .. " in universe "
                .. tostring(Config.Target.UniverseId) .. " and reconnect. Current destination differs.", 0)
        end
        if not library or not client then error("Library.Client is not loaded. Wait inside the event and reconnect.", 0) end
        local networkModule = client:FindFirstChild("Network")
        local networkPath = "Library.Client.Network"
        if not networkModule then
            networkModule = library:FindFirstChild("Network")
            networkPath = "Library.Network"
        end
        local network = requireModule(networkModule, networkPath)
        local petCmds = requireModule(client:FindFirstChild("PetCmds"), "Library.Client.PetCmds")
        if generation ~= self._generation or self._destroyed then return end
        self._network, self._petCmds = network, petCmds
        if type(self._network.Invoke) ~= "function" or type(self._network.Fire) ~= "function" then
            error(networkPath .. " lacks Invoke/Fire functions; this protocol is unsupported.", 0)
        end
        if type(self._petCmds.GetEquipped) ~= "function" then
            error("Library.Client.PetCmds lacks GetEquipped; this protocol is unsupported.", 0)
        end
        self._things = things
        self._coins = things and things:FindFirstChild("Coins")
        if not self._coins or not self._coins:IsA("Folder") then
            error("__THINGS.Coins is not an available Folder. Enter a loaded coin area and reconnect.", 0)
        end
        local worldModule = client:FindFirstChild("WorldCmds")
        if worldModule and worldModule:IsA("ModuleScript") then
            local loaded, value = pcall(require, worldModule)
            if generation ~= self._generation or self._destroyed then return end
            if loaded and type(value) == "table" and type(value.HasArea) == "function" then self._world = value end
        end
        local snapshot = self:_readSnapshot(true)
        if generation ~= self._generation or self._destroyed then return end
        self._connected = true
        self.Supported.AutoFarm, self.Supported.WalkToTarget = true, true
        local orbs = things:FindFirstChild("Orbs")
        local lootbags = things:FindFirstChild("Lootbags")
        self.Supported.AutoCollectOrbs = orbs ~= nil and orbs:IsA("Folder")
        self.Supported.AutoCollectLootbags = lootbags ~= nil and lootbags:IsA("Folder")
        self.Reason = string.format("Experimental legacy protocol probe passed (%d loaded coins, %d equipped pets); Classic Event farming still unverified in game.",
            #snapshot.Candidates, #snapshot.Pets)
    end)
    if generation ~= self._generation or self._destroyed then return self end
    if not ok then self:_block(tostring(message)) end
    self:_report()
    return self
end

function PetSim99:Snapshot()
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    local generation = self._generation
    local ok, result = pcall(self._readSnapshot, self, false)
    if generation ~= self._generation or self._destroyed then error("Snapshot canceled by reconnect or unload.", 0) end
    if not ok then self:_fail(tostring(result)) end
    return result
end

function PetSim99:Assign(target, pets, active)
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    if type(target) ~= "table" or not identifier(target.id) or not target.instance then
        error("A loaded target from Snapshot is required.", 0)
    end
    local generation = self._generation
    local function current()
        return self._connected and not self._destroyed and generation == self._generation
            and target.instance.Parent == self._coins and (not active or active())
    end
    local count, seen = 0, {}
    local assigned = self._assigned[tostring(target.id)] or {}
    local ok, message = pcall(function()
        for _, uid in ipairs(pets) do
            if not current() then break end
            if not identifier(uid) then error("Equipped pet UID is invalid.", 0) end
            local key = tostring(uid)
            if not seen[key] and not assigned[key] then
                seen[key] = true
                self:_call("Invoke", "Join Coin", target.id, { uid })
                if not current() then break end
                self:_call("Fire", "Farm Coin", target.id, uid)
                count += 1
                self._counts.FarmDispatches += 1
                assigned[key] = true
                task.wait(0.15)
            end
        end
    end)
    self:_report()
    if not ok and generation == self._generation and not self._destroyed then self:_fail(tostring(message)) end
    return count
end

function PetSim99:Collect(kind, radius, active)
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    local folderName, command, limit, supportKey
    if kind == "orbs" then
        folderName, command, limit, supportKey = "Orbs", "Claim Orbs", 20, "AutoCollectOrbs"
    elseif kind == "lootbags" then
        folderName, command, limit, supportKey = "Lootbags", "Collect Lootbag", 4, "AutoCollectLootbags"
    else error("Unknown pickup kind; expected orbs or lootbags.", 0) end
    if not self.Supported[supportKey] then error(folderName .. " collection is unavailable.", 0) end
    if not finite(radius) then error("Pickup radius must be a finite number.", 0) end
    radius = math.clamp(radius, 0, 30)
    local generation = self._generation
    local function current()
        return self._connected and not self._destroyed and generation == self._generation and (not active or active())
    end
    local count = 0
    local ok, message = pcall(function()
        local folder = self._things:FindFirstChild(folderName)
        if not folder or not folder:IsA("Folder") then error(folderName .. " is no longer loaded. Reconnect.", 0) end
        local root = self:_root()
        local ids, objects, seen = {}, {}, {}
        for _, object in ipairs(folder:GetChildren()) do
            if not current() or #ids >= limit then break end
            local position = physicalPosition(object)
            local eligibleAt = self._cooldowns[object] or -math.huge
            if object.Parent == folder and vector(position) and (root.Position - position).Magnitude <= radius
                and os.clock() - eligibleAt >= 2 and object:GetAttribute("Collected") ~= true
                and object.Name ~= "" and not seen[object.Name] then
                seen[object.Name] = true
                table.insert(ids, object.Name)
                table.insert(objects, object)
            end
        end
        if #ids == 0 or not current() then return end
        if kind == "orbs" then
            self:_call("Fire", command, ids)
            count = #ids
            self._counts.OrbIds += count
            for _, object in ipairs(objects) do self._cooldowns[object] = os.clock() end
        else
            for index, object in ipairs(objects) do
                if not current() then break end
                root = self:_root()
                local position = physicalPosition(object)
                if object.Parent == folder and vector(position) and (root.Position - position).Magnitude <= radius then
                    self:_call("Fire", command, ids[index], root.Position)
                    self._cooldowns[object] = os.clock()
                    count += 1
                    self._counts.LootbagIds += 1
                    task.wait(0.15)
                end
            end
        end
    end)
    self:_report()
    if not ok and generation == self._generation and not self._destroyed then self:_fail(tostring(message)) end
    return count
end

function PetSim99:Destroy()
    self._generation += 1
    self._destroyed = true
    self:_block("Adapter unloaded.")
    self._network, self._petCmds, self._world, self._coins, self._things = nil, nil, nil, nil, nil
    self._assigned = {}
    self._cooldowns = setmetatable({}, { __mode = "k" })
end

return PetSim99
end
end

do
__factories["Policy.luau"] = function(__require)
--!strict
-- Pure targeting and settings rules; also executed by the standalone Luau tests.
local Policy = {}

local numeric = {
    Radius = { 10, 1000 },
    FarmInterval = { 0.25, 10 },
    WalkSpeed = { 8, 100 },
    JumpPower = { 0, 150 },
}
local booleans = {
    AutoFarm = true,
    AutoCollectOrbs = true,
    AutoCollectLootbags = true,
    WalkToTarget = true,
    MovementEnabled = true,
    Fullbright = true,
    AntiIdle = true,
}

function Policy.option(key: string, value: any): (any, string?)
    if booleans[key] then
        if type(value) == "boolean" then
            return value, nil
        end
        return nil, "Expected an on/off value."
    end
    local range = numeric[key]
    if range then
        local number = tonumber(value)
        if not number or number ~= number or math.abs(number) == math.huge then
            return nil, "Enter a finite number."
        end
        return math.clamp(number, range[1], range[2]), nil
    end
    if key == "FarmMode" then
        if value == "Nearest" or value == "Weakest" or value == "Strongest" then
            return value, nil
        end
        return nil, "Unknown farm mode."
    end
    if key == "Area" or key == "NameFilter" then
        if type(value) ~= "string" then
            return nil, "Expected text."
        end
        local text = string.sub(value, 1, 100):match("^%s*(.-)%s*$") or ""
        if key == "Area" and text == "" then
            text = "All"
        end
        return text, nil
    end
    return nil, "Unknown setting: " .. tostring(key)
end

function Policy.select(candidates: { any }, options: any): any
    local selected = nil
    local filter = string.lower(options.NameFilter)
    local area = string.lower(options.Area)
    for _, item in ipairs(candidates) do
        local valid = item.health > 0
            and item.distance <= options.Radius
            and (area == "all" or string.lower(item.area) == area)
            and (filter == "" or string.find(string.lower(item.name), filter, 1, true) ~= nil)
        if not valid then
            continue
        end
        local better = selected == nil
        if selected then
            if options.FarmMode == "Weakest" and item.health ~= selected.health then
                better = item.health < selected.health
            elseif options.FarmMode == "Strongest" and item.health ~= selected.health then
                better = item.health > selected.health
            elseif item.distance ~= selected.distance then
                better = item.distance < selected.distance
            else
                better = tostring(item.id) < tostring(selected.id)
            end
        end
        if better then
            selected = item
        end
    end
    return selected
end

return Policy
end
end

do
__factories["Runtime.luau"] = function(__require)
--!nocheck
local Config = __require("Config.luau")
local Policy = __require("Policy.luau")
local Jobs = __require("Jobs.luau")
local Interface = __require("Interface.luau")
local PetSim99 = __require("PetSim99.luau")

local Lighting = game:GetService("Lighting")
local HttpService = game:GetService("HttpService")
local Runtime = {}
Runtime.__index = Runtime

function Runtime.new(player, parent)
    local self = setmetatable({
        Player = player, Alive = true, Connections = {}, Jobs = Jobs.new(),
        Options = table.clone(Config.Options), Adapter = PetSim99.new(),
        Ready = false, Failures = {}, NextAt = {},
        State = { Status = "Inspecting game...", Target = "None", EquippedPets = 0,
            Farmed = 0, CollectedOrbs = 0, CollectedLootbags = 0, LastError = "" },
    }, Runtime)
    self.Ui = Interface.mount({
        parent = parent, name = Config.Name, version = Config.Version, options = self.Options,
        onChange = function(key, value) return self:SetOption(key, value) end,
        onAction = function(action) return self:Action(action) end,
    })
    table.insert(self.Connections, player.CharacterAdded:Connect(function(character)
        for _, key in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do self.Jobs:cancel(key) end
        self:StopNavigation()
        self.LastAssignment = nil
        self.NextAt = {}
        self:RestoreMovement()
        self.Jobs:cancel("movement")
        self.Jobs:start("movement", 10, function()
            return character:WaitForChild("Humanoid", 8)
        end, function(ok, humanoid)
            if ok and humanoid and self.Options.MovementEnabled then self:ApplyMovement(humanoid) end
        end)
    end))
    table.insert(self.Connections, player.Idled:Connect(function()
        if not self.Options.AntiIdle then return end
        local ok, message = pcall(function()
            local user = game:GetService("VirtualUser")
            user:CaptureController()
            user:ClickButton2(Vector2.new(0, 0))
        end)
        if not ok then
            self.Options.AntiIdle = false
            self.AntiIdleUnavailable = true
            self.State.LastError = "Idle input unsupported: " .. tostring(message)
            self:Publish()
        end
    end))
    table.insert(self.Connections, game:GetService("TeleportService").TeleportInitFailed:Connect(function(who, _, message)
        if who == player and self.Alive then
            self.State.LastError = "Rejoin failed: " .. tostring(message)
            self:Publish()
        end
    end))
    self:Reconnect()
    self.Pulse = task.spawn(function()
        while self.Alive do
            self.Jobs:tick()
            local ok, message = pcall(function() self:Step() end)
            if not ok then
                self:StopAll()
                self.State.LastError = "Scheduler stopped: " .. tostring(message)
                self:Publish()
            end
            task.wait(0.25)
        end
    end)
    return self
end

function Runtime:StopNavigation()
    local humanoid = self.Navigating
    self.Navigating = nil
    local root = self.Player.Character and self.Player.Character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Parent and root then
        pcall(function() humanoid:MoveTo(root.Position) end)
    end
end

function Runtime:FeatureResult(key, ok, result)
    if ok then
        self.Failures[key] = 0
        if type(result) == "table" then
            for field, value in pairs(result) do self.State[field] = value end
        end
    else
        self.Failures[key] = (self.Failures[key] or 0) + 1
        self.State.LastError = key .. ": " .. tostring(result)
        if self.Adapter.Supported.AutoFarm == false then
            self.Ready = false
            for _, feature in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do
                self.Options[feature] = false
                self.Jobs:cancel(feature)
            end
            self:StopNavigation()
            self.State.Status = "Protocol rejected — reconnect required; see Status."
            self:Publish()
            return
        end
        self.NextAt[key] = os.clock() + math.min(8, 2 ^ self.Failures[key])
        if self.Failures[key] >= Config.RetryLimit then
            self.Options[key] = false
            self.State.Status = key .. " stopped after repeated errors; see Status."
            if key == "AutoFarm" then self:StopNavigation() end
        end
    end
    self:Publish()
end

function Runtime:Step()
    if not self.Ready then return end
    local now = os.clock()
    local character = self.Player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then
        for _, key in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do self.Jobs:cancel(key) end
        self:StopNavigation()
        self.LastAssignment = nil
        if self.Options.AutoFarm then self.State.Status = "Waiting for a living character..." end
        self:Publish()
        return
    end
    if self.Options.AutoFarm and not self.Jobs:busy("AutoFarm") and now >= (self.NextAt.AutoFarm or 0) then
        self.NextAt.AutoFarm = now + self.Options.FarmInterval
        self.Jobs:start("AutoFarm", Config.FarmTimeout, function()
            local snapshot = self.Adapter:Snapshot()
            if self.Player.Character ~= character or not character.Parent or not root.Parent or humanoid.Health <= 0 then
                return { Status = "Waiting for the current character..." }
            end
            if self.Options.FarmMode ~= "Nearest" and not snapshot.HealthKnown then
                error("This coin response has no reliable health data. Select Nearest priority.")
            end
            self.State.EquippedPets = #snapshot.Pets
            local target = Policy.select(snapshot.Candidates, self.Options)
            if not target then
                self:StopNavigation()
                return { Status = "No loaded targets match radius/area/name filters.", Target = "None" }
            end
            local title = target.name .. " / " .. target.area
            if #snapshot.Pets == 0 then
                self:StopNavigation()
                return { Status = "Equip pets in-game to start farming.", Target = title }
            end
            if self.Options.WalkToTarget and target.distance > 20 then
                self.Navigating = humanoid
                humanoid:MoveTo(target.position)
                return { Status = "Walking toward target...", Target = title }
            end
            self:StopNavigation()
            local sorted = {}
            for _, uid in ipairs(snapshot.Pets) do table.insert(sorted, tostring(uid)) end
            table.sort(sorted)
            local signature = table.concat(sorted, "|")
            local last = self.LastAssignment
            if last and last.Id == target.id and last.Pets == signature and now - last.Time < Config.ReassignSeconds then
                return { Status = "Recent farm requests; watching target.", Target = title }
            end
            local count = self.Adapter:Assign(target, snapshot.Pets, function()
                return self.Alive and self.Options.AutoFarm and self.Player.Character == character
                    and character.Parent ~= nil and root.Parent ~= nil and humanoid.Parent ~= nil and humanoid.Health > 0
            end)
            if count > 0 then
                self.LastAssignment = { Id = target.id, Pets = signature, Time = os.clock() }
            end
            return { Status = if count > 0 then "Farm requests sent; waiting for game response." else "No additional pet dispatches needed.", Target = title,
                Farmed = self.State.Farmed + count }
        end, function(ok, result) self:FeatureResult("AutoFarm", ok, result) end)
    end
    for _, pair in ipairs({ { "AutoCollectOrbs", "orbs", "CollectedOrbs" },
        { "AutoCollectLootbags", "lootbags", "CollectedLootbags" } }) do
        local key, kind, field = pair[1], pair[2], pair[3]
        if self.Options[key] and not self.Jobs:busy(key) and now >= (self.NextAt[key] or 0) then
            self.NextAt[key] = now + 1
            self.Jobs:start(key, Config.RequestTimeout, function()
                local count = self.Adapter:Collect(kind, self.Options.Radius, function()
                    return self.Alive and self.Options[key] and self.Player.Character == character
                        and character.Parent ~= nil and root.Parent ~= nil and humanoid.Parent ~= nil and humanoid.Health > 0
                end)
                return { [field] = self.State[field] + count }
            end, function(ok, result) self:FeatureResult(key, ok, result) end)
        end
    end
    if now >= (self.NextPublish or 0) then
        self.NextPublish = now + 1
        self:Publish()
    end
end

function Runtime:Publish()
    if not self.Alive then return end
    self.State.Options = table.clone(self.Options)
    self.State.Supported = table.clone(self.Adapter.Supported)
    self.State.Supported.AntiIdle = not self.AntiIdleUnavailable
    self.State.Capabilities = self.Adapter.Reason
        .. "\nNative Roblox UI; no external UI loader or hooks required."
        .. "\nIdle input and clipboard are tested only when used."
    self.Ui:Update(self.State)
end

function Runtime:RestoreMovement()
    local saved = self.Movement
    self.Movement = nil
    if saved and saved.Humanoid.Parent then
        pcall(function()
            saved.Humanoid.WalkSpeed = saved.WalkSpeed
            saved.Humanoid.JumpPower = saved.JumpPower
            saved.Humanoid.JumpHeight = saved.JumpHeight
        end)
    end
end

function Runtime:ApplyMovement(humanoid)
    humanoid = humanoid or (self.Player.Character and self.Player.Character:FindFirstChildOfClass("Humanoid"))
    if not humanoid then return end
    if not self.Movement or self.Movement.Humanoid ~= humanoid then
        self:RestoreMovement()
        self.Movement = { Humanoid = humanoid, WalkSpeed = humanoid.WalkSpeed,
            JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight }
    end
    humanoid.WalkSpeed = self.Options.WalkSpeed
    if humanoid.UseJumpPower then
        humanoid.JumpPower = self.Options.JumpPower
    else
        humanoid.JumpHeight = self.Options.JumpPower ^ 2 / (2 * math.max(workspace.Gravity, 1))
    end
end

function Runtime:SetLighting(enabled)
    if enabled then
        if not self.Lighting then
            self.Lighting = {}
            for _, key in ipairs({ "Brightness", "ClockTime", "FogEnd", "GlobalShadows", "Ambient", "OutdoorAmbient" }) do
                self.Lighting[key] = Lighting[key]
            end
        end
        Lighting.Brightness = 2
        Lighting.ClockTime = 14
        Lighting.FogEnd = 100000
        Lighting.GlobalShadows = false
        Lighting.Ambient = Color3.fromRGB(180, 180, 180)
        Lighting.OutdoorAmbient = Color3.fromRGB(180, 180, 180)
    elseif self.Lighting then
        for key, value in pairs(self.Lighting) do pcall(function() Lighting[key] = value end) end
        self.Lighting = nil
    end
end

function Runtime:SetOption(key, value)
    if not self.Alive then return false, "Suite is unloaded." end
    local parsed, reason = Policy.option(key, value)
    if parsed == nil then return false, reason end
    if parsed == true and self.Adapter.Supported[key] == false then
        return false, self.Adapter.Reason
    end
    if key == "AntiIdle" and parsed and self.AntiIdleUnavailable then
        return false, "This executor rejected idle input in this session."
    end
    local previous = self.Options[key]
    self.Options[key] = parsed
    if type(parsed) == "boolean" then
        if not parsed then
            self.Jobs:cancel(key)
            if key == "AutoFarm" or key == "WalkToTarget" then self:StopNavigation() end
        else
            self.Failures[key] = 0
            self.NextAt[key] = 0
        end
    end
    if key == "AutoFarm" or key == "FarmMode" or key == "Area" or key == "NameFilter" or key == "Radius" then
        self.Jobs:cancel("AutoFarm")
        self:StopNavigation()
        self.LastAssignment = nil
        self.Failures.AutoFarm = 0
        self.NextAt.AutoFarm = 0
    end
    local ok, message = pcall(function()
        if key == "MovementEnabled" then
            if parsed then self:ApplyMovement() else self:RestoreMovement() end
        elseif key == "WalkSpeed" or key == "JumpPower" then
            if self.Options.MovementEnabled then self:ApplyMovement() end
        elseif key == "Fullbright" then
            self:SetLighting(parsed)
        end
    end)
    if not ok then
        self.Options[key] = previous
        if key == "MovementEnabled" or key == "WalkSpeed" or key == "JumpPower" then
            self.Options.MovementEnabled = false
            self:RestoreMovement()
        elseif key == "Fullbright" then
            self.Options.Fullbright = false
            self:SetLighting(false)
        end
        self.State.LastError = tostring(message)
        self:Publish()
        return false, tostring(message)
    end
    self:Publish()
    return true
end

function Runtime:StopAll()
    self.Jobs:cancelAll()
    self:StopNavigation()
    self.LastAssignment = nil
    self.NextAt = {}
    for key, value in pairs(self.Options) do
        if type(value) == "boolean" then self.Options[key] = false end
    end
    self:RestoreMovement()
    self:SetLighting(false)
    self.State.Status = "Stopped — all automation disabled"
    self:Publish()
end

function Runtime:Reconnect()
    self:StopAll()
    self.Ready = false
    self.Adapter.Supported = { AutoFarm = false, AutoCollectOrbs = false, AutoCollectLootbags = false, WalkToTarget = false }
    self.State.Status = "Checking Classic Event protocol..."
    self:Publish()
    self.Jobs:start("connect", Config.RequestTimeout, function()
        return self.Adapter:Connect()
    end, function(ok, message)
        self.Ready = ok and self.Adapter.Supported.AutoFarm == true
        self.State.Status = if self.Ready then "Protocol probe passed — enable a feature to test in game" else "Compatibility probe failed — see Status"
        self.State.LastError = if self.Ready then "" elseif not ok then tostring(message) else self.Adapter.Reason
        self:Publish()
    end)
end

function Runtime:Diagnostics()
    return table.concat({
        Config.Name .. " v" .. Config.Version,
        "All automation starts disabled. Connect probes the legacy Get Coins interface.",
        self.Adapter.Report,
        "Options: " .. HttpService:JSONEncode(self.Options),
        "Last error: " .. tostring(self.State.LastError),
        "Counters represent requests, not confirmed rewards. No credentials or inventory transfer is performed.",
    }, "\n")
end

function Runtime:Action(action)
    if action == "StopAll" then self:StopAll()
    elseif action == "Reconnect" then self:Reconnect()
    elseif action == "ResetMovement" then return self:SetOption("MovementEnabled", false)
    elseif action == "Unload" then self:Destroy()
    elseif action == "Rejoin" then
        self:StopAll()
        local ok, message = pcall(function()
            game:GetService("TeleportService"):Teleport(game.PlaceId, self.Player)
        end)
        if not ok then return false, tostring(message) end
    elseif action == "CopyDiagnostics" then
        local report = self:Diagnostics()
        local copy = setclipboard or toclipboard
        if type(copy) == "function" then
            local ok, message = pcall(copy, report)
            if ok then return true end
            self.State.LastError = "Clipboard failed: " .. tostring(message)
        end
        print(report)
        self:Publish()
        return false, "Clipboard unavailable; diagnostics printed to the console."
    else return false, "Unknown action." end
    return true
end

function Runtime:Destroy()
    if not self.Alive then return end
    self:StopAll()
    self.Alive = false
    if self.Pulse then pcall(task.cancel, self.Pulse) end
    for _, connection in ipairs(self.Connections) do connection:Disconnect() end
    self.Adapter:Destroy()
    self.Ui:Destroy()
    if self.OnDestroy then self.OnDestroy() end
end

return Runtime
end
end

do
__factories["init.client.luau"] = function(__require)
--!nocheck
local Runtime = __require("Runtime.luau")

if not game:IsLoaded() then game.Loaded:Wait() end
local player = game:GetService("Players").LocalPlayer
assert(player, "Run the suite in a Roblox client, after joining the Classic Event.")
local parent = player:WaitForChild("PlayerGui", 15)
assert(parent, "PlayerGui was not available within 15 seconds.")

-- BindableEvent works in both Studio and executor environments, without getgenv.
-- A repeated run tells the prior session to restore changes before replacing it.
local markerName = "PetSimAutomationSession"
local previous = parent:FindFirstChild(markerName)
if previous then
    if not previous:IsA("BindableEvent") then
        error("A conflicting session marker already exists; unload it first.")
    end
    previous:Fire()
    local deadline = os.clock() + 3
    while previous.Parent and os.clock() < deadline do task.wait() end
    assert(not previous.Parent, "Previous suite did not unload; remove its session before retrying.")
end
local marker = Instance.new("BindableEvent")
marker.Name = markerName
marker.Parent = parent
local ok, runtime = pcall(Runtime.new, player, parent)
if not ok then
    marker:Destroy()
    error(runtime)
end
local connection
connection = marker.Event:Connect(function()
    runtime:Destroy()
end)
runtime.OnDestroy = function()
    connection:Disconnect()
    marker:Destroy()
end
end
end

local __cache = {}
local __loaded = {}
local __loading = {}
local function __require(name)
    if __loaded[name] then
        return __cache[name]
    end
    if __loading[name] then
        error("Circular module dependency: " .. name, 2)
    end
    local factory = __factories[name]
    if not factory then
        error("Unknown bundled module: " .. name, 2)
    end
    __loading[name] = true
    local ok, result = pcall(factory, __require)
    __loading[name] = nil
    if not ok then
        error("Module " .. name .. " failed: " .. tostring(result), 2)
    end
    __loaded[name] = true
    __cache[name] = result
    return result
end

return __require("init.client.luau")
